-- Pearls/Landmarks.lua: map landmarks (#10). Dungeon and raid entrances,
-- boats, zeppelins and the Deeprun Tram, and flight points on the world map
-- (zone and continent) and the minimap, with tooltips; and the zone's level
-- range on hover where Blizzard's own label has none.
--
-- The data is Data/Landmarks.lua (generated by Tools/gen_landmarks.py: the
-- client's own positions where it has them, our verified list otherwise).
-- Pins go through the vendored HereBeDragons-2.0 + Pins (BSD), which owns the
-- map maths (zoom, rotation, indoors, the continent maps). Tooltip only: no
-- click does anything (a waypoint would fight NodeRadar's), and clicks pass
-- through to the map (SetMouseClickEnabled(false)).
--
-- Coordinates: our data keeps the client tables' world order (x north, y
-- west); HereBeDragons' world x is west and y north, so every world call
-- passes (y, x).
--
-- Flight points mirror Blizzard's FlightPointDataProvider: your faction's and
-- neutral nodes, undiscovered ones marked; none on a world map where
-- C_TaxiMap.ShouldMapShowTaxiNodes says Blizzard draws them; refreshed on
-- TAXI_NODE_STATUS_CHANGED. If the runtime API gives nothing away from a
-- flight master (unmeasured until 2026-11-04), nothing is shown.
--
-- The zone level line: Blizzard's area label appends a range only when
-- C_Map.GetMapLevels gives one (AreaLabelDataProvider.lua:71); Forever's look
-- empty, so ours sits just under Blizzard's label, from our table, only then.
-- Blizzard's label is read for its position, never written.

GlassPearls = GlassPearls or {}
local GP = GlassPearls
local API = GP.API
local LM = {}
GP.Landmarks = LM

LM.KEY = "landmarks"
LM.SHOW_CONTINENT = 2   -- HBD_PINS_WORLDMAP_SHOW_CONTINENT (HereBeDragons-Pins-2.0.lua)
LM.BASE_SIZE = 16
-- Client atlases, the first one the client has wins (C_Texture.GetAtlasInfo);
-- else the file. Checked by sight on day one.
LM.ICONS = {
    dungeon = { atlas = { "Dungeon" }, file = "Interface\\TaxiFrame\\UI-Taxi-Icon-Green", tint = { 0.9, 0.75, 0.3 } },
    raid = { atlas = { "Raid" }, file = "Interface\\TaxiFrame\\UI-Taxi-Icon-Green", tint = { 0.95, 0.45, 0.3 } },
    ship = { atlas = { "TransportShip", "Vehicle-Temporary-Zone-Boat" }, file = "Interface\\TaxiFrame\\UI-Taxi-Icon-Green", tint = { 0.5, 0.75, 1 } },
    zeppelin = { atlas = { "TransportZeppelin", "TransportShip" }, file = "Interface\\TaxiFrame\\UI-Taxi-Icon-Green", tint = { 0.9, 0.5, 0.4 } },
    tram = { atlas = { "TransportTram", "TransportShip" }, file = "Interface\\TaxiFrame\\UI-Taxi-Icon-Green", tint = { 0.8, 0.8, 0.8 } },
    flight = { atlas = { "TaxiNode_Neutral" }, file = "Interface\\TaxiFrame\\UI-Taxi-Icon-Green" },
}
LM.KIND_LABEL = { dungeon = "Dungeon entrance", raid = "Raid entrance", ship = "Ship", zeppelin = "Zeppelin",
                  tram = "Deeprun Tram", flight = "Flight master" }
LM.SIDE_NAME = { A = "Alliance", H = "Horde" }
local FACTION = { Neutral = 0, Horde = 1, Alliance = 2 }   -- Enum.FlightPathFaction (TaxiMapDocumentation.lua:95)

local frames = { world = {}, mini = {} }   -- pools, one per display (HereBeDragons reparents each frame)
local used = { world = 0, mini = 0 }
LM.placed = {}                              -- what was added this build, for the tests and /gpearls
local label                                 -- the zone level line
local events = CreateFrame("Frame")

local function setting(name) return GP.Pearls.Setting(LM.KEY, name) end

local function pins()
    local stub = rawget(_G, "LibStub")
    return stub and stub("HereBeDragons-Pins-2.0", true)
end

local function plainString(v)
    if API.IsSecret(v) or type(v) ~= "string" or v == "" then return nil end
    return v
end

local function playerFaction()
    local ok, f = pcall(UnitFactionGroup, "player")
    return ok and plainString(f) or nil
end

-- The first atlas the client has, or nil.
local function atlasFor(list)
    local T = rawget(_G, "C_Texture")
    if not (T and T.GetAtlasInfo) then return nil end
    for _, name in ipairs(list or {}) do
        local ok, info = pcall(T.GetAtlasInfo, name)
        if ok and info then return name end
    end
end

--------------------------------------------------------------------------------
-- Tooltips

-- A level range coloured as Blizzard's zone label colours one.
local function levelText(lo, hi)
    if type(lo) ~= "number" then return "" end
    local text = hi and (hi ~= lo and (lo .. "-" .. hi) or tostring(lo)) or (lo .. "+")
    -- Blizzard's rule (AreaLabelDataProvider.lua:88-95): below the range, the
    -- colour of its minimum; above it, of its maximum - 2; inside, "difficult".
    local color
    local difficulty, colors = rawget(_G, "GetQuestDifficultyColor"), rawget(_G, "QuestDifficultyColors")
    local okL, lvl = pcall(UnitLevel, "player")
    lvl = okL and not API.IsSecret(lvl) and type(lvl) == "number" and lvl or nil
    if lvl and difficulty then
        local ok, c
        if lvl < lo then ok, c = pcall(difficulty, lo)
        elseif hi and lvl > hi then ok, c = pcall(difficulty, hi - 2)
        else ok, c = true, colors and colors["difficult"] end
        if ok and type(c) == "table" and type(c.r) == "number" then color = c end
    end
    if color then
        return string.format("|cff%02x%02x%02x(%s)|r", color.r * 255, color.g * 255, color.b * 255, text)
    end
    return "(" .. text .. ")"
end
LM.LevelText = levelText

-- A dungeon's name: the client's own (localized) when GetLFGDungeonInfo gives
-- a plain string for that ID, else our English one.
local function dungeonName(e)
    local info = rawget(_G, "GetLFGDungeonInfo")
    if info then
        local ok, name = pcall(info, e.lfg)
        name = ok and plainString(name)
        if name then return name end
    end
    return e.name
end
LM.DungeonName = dungeonName

-- The tooltip's lines for one landmark: { { text, r, g, b }, ... }.
function LM.TooltipLines(entry)
    local lines = {}
    local function add(text, r, g, b) lines[#lines + 1] = { text, r or 1, g or 1, b or 1 } end
    if entry.list then
        local raids = 0
        for _, e in ipairs(entry.list) do
            add(dungeonName(e) .. "  " .. levelText(e.min, e.max), 1, 0.82, 0)
            if e.raid then raids = raids + 1 end
        end
        add(raids == #entry.list and LM.KIND_LABEL.raid or (raids > 0 and "Dungeon and raid entrance" or LM.KIND_LABEL.dungeon),
            0.8, 0.8, 0.8)
    elseif entry.kind == "flight" then
        add(entry.name or LM.KIND_LABEL.flight, 1, 0.82, 0)
        add(LM.KIND_LABEL.flight, 0.8, 0.8, 0.8)
        if entry.undiscovered then
            add(rawget(_G, "UNDISCOVERED_NEUTRAL_FLIGHTPOINT") or "Undiscovered", 0.6, 0.6, 0.6)
        end
    else
        local title = entry.name
        local mine = playerFaction()
        local side = LM.SIDE_NAME[entry.sides]   -- nil for "AH": both sides
        if side and mine and side ~= mine then title = title .. "  |cffff6060(" .. side .. " only)|r" end
        add(title, 1, 0.82, 0)
        add(LM.KIND_LABEL[entry.kind] or entry.kind, 0.8, 0.8, 0.8)
        for _, to in ipairs(entry.routes or {}) do add("To " .. to) end
    end
    return lines
end

local function onEnter(f)
    if not f.entry then return end
    GameTooltip:SetOwner(f, "ANCHOR_RIGHT")
    for i, l in ipairs(LM.TooltipLines(f.entry)) do
        if i == 1 then GameTooltip:SetText(l[1], l[2], l[3], l[4]) else GameTooltip:AddLine(l[1], l[2], l[3], l[4], true) end
    end
    GameTooltip:Show()
end
local function onLeave() GameTooltip:Hide() end

--------------------------------------------------------------------------------
-- Pins

local function acquire(display, kind, atlas)
    used[display] = used[display] + 1
    local f = frames[display][used[display]]
    if not f then
        f = CreateFrame("Frame", nil, UIParent)
        f.tex = f:CreateTexture(nil, "OVERLAY")
        f.tex:SetAllPoints(f)
        -- Hover shows the tooltip; clicks go through to the map (tooltip only).
        f:SetMouseClickEnabled(false)
        f:SetMouseMotionEnabled(true)
        f:SetScript("OnEnter", onEnter)
        f:SetScript("OnLeave", onLeave)
        frames[display][used[display]] = f
    end
    local icon = LM.ICONS[kind]
    local size = LM.BASE_SIZE * (setting("size") or 100) / 100
    f:SetSize(size, size)
    atlas = atlas or atlasFor(icon.atlas)
    if atlas then
        f.tex:SetAtlas(atlas)
        f.tex:SetVertexColor(1, 1, 1)
    else
        f.tex:SetTexture(icon.file)
        local t = icon.tint or { 1, 1, 1 }
        f.tex:SetVertexColor(t[1], t[2], t[3])
    end
    f:Show()
    return f
end

local function record(display, entry, ok)
    LM.placed[#LM.placed + 1] = { display = display, entry = entry, ok = ok ~= false }
    if ok == false then API.Fail("pearl landmarks pin", (entry.name or entry.key or "?") .. " on the " .. display) end
end

-- One landmark from world coordinates (our data's x north, y west).
local function addWorld(P, entry, kind, worldOn, miniOn)
    if worldOn then
        local f = acquire("world", kind)
        f.entry = entry
        record("world", entry, P:AddWorldMapIconWorld(LM, f, entry.c, entry.y, entry.x, LM.SHOW_CONTINENT))
    end
    if miniOn then
        local f = acquire("mini", kind)
        f.entry = entry
        record("mini", entry, P:AddMinimapIconWorld(LM, f, entry.c, entry.y, entry.x, false))
    end
end

-- Flight points of one zone, from the client at runtime (map coordinates).
local function addFlights(P, uiMapID, worldOn, miniOn)
    local Taxi = rawget(_G, "C_TaxiMap")
    if not (Taxi and Taxi.GetTaxiNodesForMap) then return end
    local ok, nodes = pcall(Taxi.GetTaxiNodesForMap, uiMapID)
    if not ok or type(nodes) ~= "table" then return end
    local mine = playerFaction()
    local okS, blizzard = pcall(Taxi.ShouldMapShowTaxiNodes, uiMapID)
    local onWorld = worldOn and not (okS and blizzard == true)
    for _, n in ipairs(nodes) do
        local pos = type(n) == "table" and n.position
        local faction = n.faction
        local show = (faction == FACTION.Horde and mine == "Horde") or (faction == FACTION.Alliance and mine == "Alliance")
            or (faction ~= FACTION.Horde and faction ~= FACTION.Alliance)
        local x, y = pos and pos.x, pos and pos.y
        if show and type(x) == "number" and type(y) == "number" and not API.IsSecret(x) then
            local entry = { kind = "flight", name = plainString(n.name), undiscovered = n.isUndiscovered == true,
                            map = uiMapID, mx = x, my = y }
            local atlas = plainString(n.atlasName)
            atlas = atlas and atlasFor({ atlas }) or nil
            if onWorld then
                local f = acquire("world", "flight", atlas)
                f.entry = entry
                if entry.undiscovered then f.tex:SetDesaturated(true) end
                record("world", entry, P:AddWorldMapIconMap(LM, f, uiMapID, x, y, LM.SHOW_CONTINENT))
            end
            if miniOn then
                local f = acquire("mini", "flight", atlas)
                f.entry = entry
                record("mini", entry, P:AddMinimapIconMap(LM, f, uiMapID, x, y, true, false))
            end
        end
    end
end

local function clear()
    local P = pins()
    if P then
        P:RemoveAllWorldMapIcons(LM)
        P:RemoveAllMinimapIcons(LM)
    end
    for display, list in pairs(frames) do
        for i = 1, used[display] do
            list[i]:Hide()
            list[i].entry = nil
            list[i].tex:SetDesaturated(false)
        end
        used[display] = 0
    end
    LM.placed = {}
end

-- Everything again, per the settings: at Enable, after a settings change, and
-- on TAXI_NODE_STATUS_CHANGED.
function LM.Build()
    clear()
    local P = pins()
    local data = GP.LandmarkData
    if not P or not data then
        API.Fail("pearl landmarks", not P and "HereBeDragons-Pins-2.0 not loaded" or "no data")
        return false
    end
    for _, e in ipairs(data.entrances) do
        addWorld(P, e, e.kind, setting("entrancesWorld"), setting("entrancesMinimap"))
    end
    for _, t in ipairs(data.transports) do
        addWorld(P, t, t.kind, setting("transportsWorld"), setting("transportsMinimap"))
    end
    if setting("flightsWorld") or setting("flightsMinimap") then
        for _, uiMapID in ipairs(data.zonemaps or {}) do
            addFlights(P, uiMapID, setting("flightsWorld"), setting("flightsMinimap"))
        end
    end
    return true
end

--------------------------------------------------------------------------------
-- The zone level line under Blizzard's area label.

-- The area label provider's label frame, read from the map's providers.
local function areaLabel()
    local map = rawget(_G, "WorldMapFrame")
    local providers = map and map.dataProviders
    if type(providers) ~= "table" then return nil end
    for provider in pairs(providers) do
        if type(provider) == "table" and type(provider.Label) == "table" then return provider.Label end
    end
end

-- What the line should say now: text, or nil to hide it.
function LM.ZoneLevelText()
    local map = rawget(_G, "WorldMapFrame")
    if not (map and map:IsShown() and setting("zoneLevels")) then return nil end
    if not (map.IsCanvasMouseFocus and map:IsCanvasMouseFocus()) then return nil end
    local mapID = map:GetMapID()
    local x, y = map:GetNormalizedCursorPosition()
    if type(mapID) ~= "number" or type(x) ~= "number" or type(y) ~= "number" then return nil end
    local ok, info = pcall(C_Map.GetMapInfoAtPosition, mapID, x, y)
    if not ok or type(info) ~= "table" or not info.mapID or info.mapID == mapID then return nil end
    -- Blizzard shows its own range when the client has one: then stay out.
    local okL, lo = pcall(C_Map.GetMapLevels, info.mapID)
    if okL and type(lo) == "number" and lo > 0 then return nil end
    local ours = GP.LandmarkData and GP.LandmarkData.zones[info.mapID]
    if not ours then return nil end
    return levelText(ours[1], ours[2])
end

local function updateLabel()
    if not label then return end
    local text = LM.ZoneLevelText()
    if not text then return label.text:Hide() end
    local blizzard = areaLabel()
    label.text:ClearAllPoints()
    if blizzard then
        label.text:SetPoint("TOP", blizzard, "BOTTOM", 0, -2)
    else
        label.text:SetPoint("TOP", label, "TOP", 0, -40)
    end
    label.text:SetText(text)
    label.text:Show()
end

local function ensureLabel()
    local map = rawget(_G, "WorldMapFrame")
    if label or not map then return end
    -- Our own frame on the map (shown and hidden with it); its OnUpdate runs
    -- only while the map is shown.
    label = CreateFrame("Frame", nil, map)
    label:SetAllPoints(map)
    label:SetFrameStrata("HIGH")
    label.text = label:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
    label.text:Hide()
    label:SetScript("OnUpdate", updateLabel)
end

--------------------------------------------------------------------------------
-- The pearl.

events:SetScript("OnEvent", function(_, event)
    if event == "TAXI_NODE_STATUS_CHANGED" or event == "PLAYER_ENTERING_WORLD" then LM.Build() end
end)

local function enable()
    LM.enabled = true
    ensureLabel()
    if label then label:Show() end
    API.RegisterEvents(events, { "TAXI_NODE_STATUS_CHANGED", "PLAYER_ENTERING_WORLD" })
    LM.Build()
end

local function disable()
    LM.enabled = false
    events:UnregisterAllEvents()
    clear()
    if label then
        label.text:Hide()
        label:Hide()
    end
end

GP.Pearls.Register({
    key = LM.KEY,
    name = "Map landmarks",
    desc = "Dungeon and raid entrances, boats, zeppelins, the tram and flight points on the world map and minimap, "
        .. "and each zone's level range.",
    help = "Icons on the world map (zone and continent) and the minimap. Hover one for its tooltip: a dungeon's name "
        .. "and suggested levels, a boat's or zeppelin's destinations (the other faction's are marked), a flight "
        .. "master's name. Clicks go through to the map. Hovering a zone on a continent map shows its level range "
        .. "under its name, when the game shows none.",
    default = true,
    category = "Interface",
    section = "Maps",
    defaults = {
        entrancesWorld = true, entrancesMinimap = true,
        transportsWorld = true, transportsMinimap = true,
        flightsWorld = true, flightsMinimap = true,
        zoneLevels = true,
        size = 100,
    },
    ranges = { size = { 60, 160 } },
    Enable = enable,
    Disable = disable,
    onSettingChanged = function(name)
        if not LM.enabled then return end
        if name ~= "zoneLevels" then LM.Build() end
    end,
    configure = function(panel, refreshers)
        local P = GP.Pearls
        local function check(anchor, text, name, x, y)
            local cb, refresh = GP.UI.Check(panel, text,
                function() return P.Setting(LM.KEY, name) end, function(on) P.SetSetting(LM.KEY, name, on) end)
            cb:SetPoint("TOPLEFT", anchor, "BOTTOMLEFT", x or 0, y or -4)
            refreshers[#refreshers + 1] = refresh
            return cb
        end
        local head = GP.UI.Header(panel, "World map")
        head:SetPoint("TOPLEFT", panel, "TOPLEFT", 0, 0)
        local a = check(head, "Dungeon and raid entrances", "entrancesWorld", -4, -6)
        a = check(a, "Boats, zeppelins and the tram", "transportsWorld")
        a = check(a, "Flight points (where the game shows none)", "flightsWorld")
        a = check(a, "Zone level range on hover", "zoneLevels")
        local mini = GP.UI.Header(panel, "Minimap")
        mini:SetPoint("TOPLEFT", a, "BOTTOMLEFT", 4, -14)
        a = check(mini, "Dungeon and raid entrances", "entrancesMinimap", -4, -6)
        a = check(a, "Boats, zeppelins and the tram", "transportsMinimap")
        a = check(a, "Flight points", "flightsMinimap")
        local sizeHead = GP.UI.Header(panel, "Icon size")
        sizeHead:SetPoint("TOPLEFT", a, "BOTTOMLEFT", 4, -14)
        local _, _, refreshSize = GP.UI.Radios(panel, sizeHead,
            { { 80, "Small" }, { 100, "Normal" }, { 130, "Large" } },
            function() return P.Setting(LM.KEY, "size") end, function(v) P.SetSetting(LM.KEY, "size", v) end)
        refreshers[#refreshers + 1] = refreshSize
    end,
})

LM._test = {
    frames = frames, used = used, events = events,
    label = function() return label end, update = updateLabel,
}
